  "content": "#include <cmath>
#include <cstdint>
#include <omp.h>

struct Grid {
    const float* b;
    int nr, nt, np;
    double lr0, dlr, t0, dt, dp;
};

static inline void field(const Grid& g, const double x[3], double out[3], double& r) {
    r = std::sqrt(x[0] * x[0] + x[1] * x[1] + x[2] * x[2]);
    double th = std::acos(std::fmax(-1.0, std::fmin(1.0, x[2] / r)));
    double ph = std::atan2(x[1], x[0]);
    if (ph < 0) ph += 2 * M_PI;
    double u = (std::log(r) - g.lr0) / g.dlr;
    double v = (th - g.t0) / g.dt;
    double w = ph / g.dp;
    u = std::fmin(std::fmax(u, 0.0), g.nr - 1.000001);
    v = std::fmin(std::fmax(v, 0.0), g.nt - 1.000001);
    int i = (int)u, j = (int)v, k = (int)w;
    double fu = u - i, fv = v - j, fw = w - k;
    k %= g.np;
    int k1 = (k + 1) % g.np;
    out[0] = out[1] = out[2] = 0.0;
    for (int a = 0; a < 2; ++a) {
        double wa = a ? fu : 1 - fu;
        for (int c = 0; c < 2; ++c) {
            double wc = wa * (c ? fv : 1 - fv);
            const float* p0 = g.b + 3 * ((size_t)((i + a) * g.nt + (j + c)) * g.np + k);
            const float* p1 = g.b + 3 * ((size_t)((i + a) * g.nt + (j + c)) * g.np + k1);
            double w0 = wc * (1 - fw), w1 = wc * fw;
            for (int q = 0; q < 3; ++q) out[q] += w0 * p0[q] + w1 * p1[q];
        }
    }
}

static inline double unit(const Grid& g, const double x[3], double d[3], double s) {
    double r, B[3];
    field(g, x, B, r);
    double m = std::sqrt(B[0] * B[0] + B[1] * B[1] + B[2] * B[2]);
    double f = m > 0 ? s / m : 0.0;
    for (int q = 0; q < 3; ++q) d[q] = B[q] * f;
    return m;
}

extern "C" void trace(const float* cube, int nr, int nt, int np, double lr0, double dlr, double t0,
                      double dt, double dp, double rmin, double rmax, int n, const double* seeds,
                      const int* updown, double h, int maxstep, double* out, int* status, int nthreads) {
    Grid g{cube, nr, nt, np, lr0, dlr, t0, dt, dp};
    omp_set_num_threads(nthreads);
#pragma omp parallel for schedule(dynamic, 64)
    for (int s = 0; s < n; ++s) {
        double r0 = seeds[3 * s], th = seeds[3 * s + 1], ph = seeds[3 * s + 2];
        double x[3] = {r0 * std::sin(th) * std::cos(ph), r0 * std::sin(th) * std::sin(ph), r0 * std::cos(th)};
        double B[3], r;
        field(g, x, B, r);
        double br = (B[0] * x[0] + B[1] * x[1] + B[2] * x[2]) / r;
        double sg = (br >= 0 ? 1.0 : -1.0) * updown[s];
        double b0 = std::sqrt(B[0] * B[0] + B[1] * B[1] + B[2] * B[2]);
        double len = 0.0, xp[3];
        int st = 3, it;
        for (it = 0; it < maxstep; ++it) {
            double rr = std::sqrt(x[0] * x[0] + x[1] * x[1] + x[2] * x[2]);
            double hs = h * rr;
            double k1[3], k2[3], k3[3], k4[3], y[3];
            if (unit(g, x, k1, sg) == 0.0) { st = 2; break; }
            for (int q = 0; q < 3; ++q) y[q] = x[q] + 0.5 * hs * k1[q];
            unit(g, y, k2, sg);
            for (int q = 0; q < 3; ++q) y[q] = x[q] + 0.5 * hs * k2[q];
            unit(g, y, k3, sg);
            for (int q = 0; q < 3; ++q) y[q] = x[q] + hs * k3[q];
            unit(g, y, k4, sg);
            for (int q = 0; q < 3; ++q) {
                xp[q] = x[q];
                x[q] += hs * (k1[q] + 2 * k2[q] + 2 * k3[q] + k4[q]) / 6.0;
            }
            len += hs;
            double rn = std::sqrt(x[0] * x[0] + x[1] * x[1] + x[2] * x[2]);
            if (rn <= rmin || rn >= rmax) {
                double rt = rn <= rmin ? rmin : rmax;
                double f = (rt - rr) / (rn - rr);
                for (int q = 0; q < 3; ++q) x[q] = xp[q] + f * (x[q] - xp[q]);
                double rx = std::sqrt(x[0] * x[0] + x[1] * x[1] + x[2] * x[2]);
                for (int q = 0; q < 3; ++q) x[q] *= rt / rx;
                len -= (1 - f) * hs;
                st = rn <= rmin ? 0 : 1;
                break;
            }
        }
        double rf;
        field(g, x, B, rf);
        double* o = out + 7 * s;
        o[0] = rf;
        o[1] = std::acos(std::fmax(-1.0, std::fmin(1.0, x[2] / rf)));
        o[2] = std::atan2(x[1], x[0]);
        if (o[2] < 0) o[2] += 2 * M_PI;
        o[3] = b0;
        o[4] = std::sqrt(B[0] * B[0] + B[1] * B[1] + B[2] * B[2]);
        o[5] = len;
        o[6] = it;
        status[s] = st;
    }
}
